syntax:
To define a move constructor and move assignment operator:

class MyClass {
public:
    MyClass(MyClass&& other) noexcept {  // Move constructor
        // Implementation: Transfer resources, e.g., std::swap(*this, other);
        data_ = std::move(other.data_);  // Note: std::move casts to rvalue reference
    }

    MyClass& operator=(MyClass&& other) noexcept {  // Move assignment
        if (this != &other) {
            // Clean up existing resources
            data_ = std::move(other.data_);  // Transfer ownership
        }
        return *this;
    }
private:
    std::vector<int> data_;  // Example resource
};

Implementation note: The compiler will generate code that checks if the argument is an rvalue; if not, it might fall back to copy semantics, but with 'noexcept', it optimizes for exception safety and inlines transfers for performance.

code_example:
#include <iostream>
#include <vector>
#include <utility>  // For std::move

class MyClass {
public:
    MyClass(std::vector<int> data) : data_(std::move(data)) {}  // Constructor taking rvalue
    MyClass(MyClass&& other) noexcept : data_(std::move(other.data_)) {
        std::cout << "Move constructor called" << std::endl;
    }
    MyClass(const MyClass& other) : data_(other.data_) {
        std::cout << "Copy constructor called" << std::endl;
    }
    ~MyClass() { std::cout << "Destructor called" << std::endl; }

    void print() const {
        for (int val : data_) { std::cout << val << " "; }
        std::cout << std::endl;
    }

private:
    std::vector<int> data_;
};

int main() {
    MyClass original(std::vector<int>{1, 2, 3, 4, 5});  // Creates a vector
    MyClass moved(std::move(original));  // Invokes move constructor
    moved.print();  // Output: 1 2 3 4 5
    return 0;
}
